1	import {
2	  runScenario,
3	  type Scenario,
4	  type ScenarioResult,
5	} from "./claim-office.js";
6	
7	const readStdin = async (): Promise<string> => {
8	  const chunks: string[] = [];
9	  process.stdin.setEncoding("utf8");
10	  for await (const chunk of process.stdin) {
11	    chunks.push(chunk);
12	  }
13	  return chunks.join("");
14	};
15	
16	// The one point where an untrusted string becomes a typed value. The assertion
17	// is unchecked: nothing here verifies that the parsed JSON is really a Scenario.
18	// Naming it marks the boundary so that the day a malformed-input case needs
19	// rejecting, there is a function to put the check in rather than a cast buried
20	// in a pipeline.
21	const parseScenario = (input: string): Scenario => JSON.parse(input) as Scenario;
22	
23	const writeResult = (result: ScenarioResult): void => {
24	  process.stdout.write(JSON.stringify(result));
25	};
26	
27	const main = async (): Promise<void> => {
28	  writeResult(runScenario(parseScenario(await readStdin())));
29	};
30	
31	// The mirror of parseScenario: an untyped value becoming a described one. A
32	// thrown value need not be an Error, so this narrows rather than asserts —
33	// String covers the case no throw site here produces.
34	const describeError = (error: unknown): string =>
35	  error instanceof Error ? error.message : String(error);
36	
37	// A rejected scenario is a report to the customer, not a crash: stderr carries
38	// the description and the exit code carries the rejection. Setting exitCode
39	// rather than calling process.exit lets the streams flush first.
40	try {
41	  await main();
42	} catch (error) {
43	  process.stderr.write(`${describeError(error)}\n`);
44	  process.exitCode = 1;
45	}
